using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// Sprite loader for the sea battles. The pixel art lives in Assets/Resources/Sprites (ship_*_hull / ship_*_rig, crew_*, crate, barrel, rock_*, ...),
/// generated by tools/naval/gen_naval_art.py. Everything is imported at 16 pixels per unit with point filtering.
/// </summary>
public static class NavalArt
{
    public const float Ppu = 16f;
    static readonly Dictionary<string, Sprite> cache = new Dictionary<string, Sprite>();
    static Sprite ringSprite, discSprite;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    static void ResetStatics() { cache.Clear(); ringSprite = null; discSprite = null; }

    public static Sprite Get(string name, float pivotX = 0.5f)
    {
        string key = name + "|" + pivotX;
        Sprite s;
        if (cache.TryGetValue(key, out s) && s != null) return s;
        Texture2D t = GameAssets.Texture(name);
        if (t == null)
        {
            Debug.LogWarning("[NavalArt] missing sprite: Resources/Sprites/" + name);
            s = GameAssets.Glow;
        }
        else
        {
            bool clean = name.StartsWith("ship_");          // smooth 64 ppu art for the ships, pixel art for the rest
            if (clean) { t.filterMode = FilterMode.Bilinear; t.wrapMode = TextureWrapMode.Clamp; }
            s = Sprite.Create(t, new Rect(0, 0, t.width, t.height), new Vector2(pivotX, 0.5f), clean ? 64f : Ppu);
        }
        cache[key] = s;
        return s;
    }

    /// <summary>Thin circle outline, 2 world units across at scale 1 (scale = radius).</summary>
    public static Sprite RingSprite
    {
        get
        {
            if (ringSprite != null) return ringSprite;
            const int n = 96;
            var tex = new Texture2D(n, n, TextureFormat.RGBA32, false) { filterMode = FilterMode.Bilinear };
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                {
                    float dx = (x - n / 2f + 0.5f) / (n / 2f), dy = (y - n / 2f + 0.5f) / (n / 2f);
                    float d = Mathf.Sqrt(dx * dx + dy * dy);
                    float a = Mathf.Clamp01(1f - Mathf.Abs(d - 0.93f) / 0.05f);
                    tex.SetPixel(x, y, new Color(1f, 1f, 1f, a));
                }
            tex.Apply();
            ringSprite = Sprite.Create(tex, new Rect(0, 0, n, n), new Vector2(0.5f, 0.5f), n / 2f);
            return ringSprite;
        }
    }

    /// <summary>Solid disc with a soft edge, 2 world units across at scale 1.</summary>
    public static Sprite DiscSprite
    {
        get
        {
            if (discSprite != null) return discSprite;
            const int n = 64;
            var tex = new Texture2D(n, n, TextureFormat.RGBA32, false) { filterMode = FilterMode.Bilinear };
            for (int y = 0; y < n; y++)
                for (int x = 0; x < n; x++)
                {
                    float dx = (x - n / 2f + 0.5f) / (n / 2f), dy = (y - n / 2f + 0.5f) / (n / 2f);
                    float d = Mathf.Sqrt(dx * dx + dy * dy);
                    tex.SetPixel(x, y, new Color(1f, 1f, 1f, Mathf.Clamp01((1f - d) / 0.08f)));
                }
            tex.Apply();
            discSprite = Sprite.Create(tex, new Rect(0, 0, n, n), new Vector2(0.5f, 0.5f), n / 2f);
            return discSprite;
        }
    }
}
